type RequestWithAuth=express.Request & { userId?:string; orgId?:string; role?:string };
interface RazorRequest extends express.Request { rawBody?: Buffer }
async function authenticate(req:RequestWithAuth,res:express.Response,next:express.NextFunction){
  const token=req.header('authorization')?.replace(/^Bearer\s+/i,''); if(!token){res.status(401).json({error:'Sign in to continue.'});return;}
  const scoped=createClient(env.SUPABASE_URL,env.SUPABASE_ANON_KEY,{global:{headers:{Authorization:`Bearer ${token}`}},auth:{persistSession:false}});
  const {data:{user},error}=await scoped.auth.getUser(); if(error||!user){res.status(401).json({error:'Your session has expired.'});return;}
  const orgId=String(req.header('x-organization-id')||''); const {data:member}=await admin.from('organization_members').select('role').eq('user_id',user.id).eq('organization_id',orgId).maybeSingle();
  if(!member){res.status(403).json({error:'You do not have access to this studio.'});return;}const {data:organization}=await admin.from('organizations').select('status').eq('id',orgId).maybeSingle();if(organization?.status==='SUSPENDED'){res.status(403).json({error:'This studio is suspended. Contact platform support.'});return;} req.userId=user.id;req.orgId=orgId;req.role=member.role;next();
}
function allowRoles(req:RequestWithAuth,res:express.Response,roles:string[]){if(req.role==='SUPER_ADMIN')return true;if(!req.role||!roles.includes(req.role)){res.status(403).json({error:'Your studio role does not allow this action.'});return false;}return true;}
