api.post('/studios',async(req,res)=>{const token=req.header('authorization')?.replace(/^Bearer\s+/i,'');if(!token){res.status(401).json({error:'Sign in to continue.'});return;}const scoped=createClient(env.SUPABASE_URL,env.SUPABASE_ANON_KEY,{global:{headers:{Authorization:`Bearer ${token}`}},auth:{persistSession:false}});const {data:{user},error}=await scoped.auth.getUser();if(error||!user){res.status(401).json({error:'Your session has expired.'});return;}const name=z.string().trim().min(2).max(140).safeParse(req.body.name);if(!name.success){res.status(400).json({error:'Enter a studio name.'});return;}const {data,error:createError}=await admin.rpc('create_studio_for_user',{p_user_id:user.id,p_name:name.data});if(createError){res.status(400).json({error:'Could not create your studio workspace.'});return;}res.status(201).json({organizationId:data,status:'PENDING_APPROVAL'});});api.post('/booking-requests/:id/convert',authenticate,async(req:RequestWithAuth,res)=>{
  if(!allowRoles(req,res,['OWNER','ADMIN','PHOTOGRAPHER']))return;
  const {data,error}=await admin.rpc('convert_booking_request',{
    p_organization_id:req.orgId,
    p_request_id:req.params.id
  });
  if(error){
    const message=error.message||'';
    if(message.includes('APPOINTMENT_NOT_FOUND')){res.status(404).json({error:'Appointment request not found.'});return;}
    if(message.includes('APPOINTMENT_MUST_BE_ACCEPTED')){res.status(409).json({error:'Confirm the appointment request before creating its project.'});return;}
    if(message.includes('APPOINTMENT_ALREADY_CONVERTED')){res.status(409).json({error:'This request was converted earlier. Refresh the request list to see its project.'});return;}
    res.status(400).json({error:'Could not convert this appointment into a project.'});return;
  }
  const project=Array.isArray(data)?data[0]:data;
  if(!project?.project_id){res.status(500).json({error:'The project was not returned after conversion.'});return;}
  res.status(project.already_converted?200:201).json({
    project:{id:project.project_id,name:project.project_name},
    alreadyConverted:Boolean(project.already_converted)
  });
});
