  const {data:project}=await admin.from('projects').select('id').eq('id',f.projectId).eq('organization_id',req.orgId).maybeSingle();if(!project){res.status(404).json({error:'Project not found in this studio.'});return;}if(f.mediaId){const {data:target}=await admin.from('media').select('id').eq('id',f.mediaId).eq('organization_id',req.orgId).eq('project_id',f.projectId).maybeSingle();if(!target){res.status(404).json({error:'Media preview target is invalid.'});return;}}
