 const {data:reserved,error:reserveError}=await admin.rpc('reserve_org_storage',{p_org_id:req.orgId,p_bytes:f.sizeBytes});if(reserveError||!reserved){res.status(413).json({error:'This upload would exceed the studio storage limit.'});return;}const id=randomUUID();const meta=(name:string,value:string)=>`${name} ${Buffer.from(value).toString('base64')}`;
 try{const response=await fetch(`https://api.cloudflare.com/client/v4/accounts/${env.CLOUDFLARE_ACCOUNT_ID}/stream?direct_user=true`,{method:'POST',headers:{Authorization:`Bearer ${env.CLOUDFLARE_STREAM_API_TOKEN}`,'Tus-Resumable':'1.0.0','Upload-Length':String(f.sizeBytes),'Upload-Metadata':[meta('name',f.filename),meta('maxDurationSeconds','14400'),meta('meta',JSON.stringify({uploadId:id,organizationId:req.orgId,projectId:f.projectId}))].join(',')}});const location=response.headers.get('Location');const streamId=response.headers.get('stream-media-id');if(!response.ok||!location||!streamId)throw new Error('Stream session failed');const {error}=await admin.from('upload_sessions').insert({id,organization_id:req.orgId,project_id:f.projectId,gallery_id:f.galleryId??null,provider:'STREAM',provider_upload_id:streamId,provider_upload_url:location,filename:f.filename,mime_type:f.mimeType,file_size_bytes:f.sizeBytes,status:'INITIATED',expires_at:new Date(Date.now()+86400000).toISOString()});if(error)throw error;res.status(201).json({uploadId:id,uploadUrl:location,streamMediaId:streamId,chunkSizeBytes:50*1024*1024});}catch{await admin.rpc('release_org_storage',{p_org_id:req.orgId,p_bytes:f.sizeBytes});res.status(502).json({error:'Could not start the resumable video upload.'});}
