api.patch('/booking-requests/:id',authenticate,async(req:RequestWithAuth,res)=>{
  if(!allowRoles(req,res,['OWNER','ADMIN','PHOTOGRAPHER']))return;
  const nextStatus=z.enum(['CONTACTED','ACCEPTED','DECLINED']).safeParse(req.body.status);
  if(!nextStatus.success){res.status(400).json({error:'Choose a valid next status for this request.'});return;}
  const {data:current,error:readError}=await admin.from('booking_requests')
    .select('id,status').eq('id',req.params.id).eq('organization_id',req.orgId).maybeSingle();
  if(readError||!current){res.status(404).json({error:'Request not found.'});return;}
  const transitions:Record<string,string[]>={NEW:['CONTACTED','ACCEPTED','DECLINED'],CONTACTED:['ACCEPTED','DECLINED']};
  if(!transitions[current.status]?.includes(nextStatus.data)){
    res.status(409).json({error:'This request has already moved to another stage. Refresh the request list.'});return;
  }
  const {data,error}=await admin.from('booking_requests').update({
    status:nextStatus.data,updated_at:new Date().toISOString()
  }).eq('id',req.params.id).eq('organization_id',req.orgId).eq('status',current.status).select('id,status').maybeSingle();
  if(error||!data){res.status(409).json({error:'This request changed while you were reviewing it. Refresh the request list.'});return;}
  res.json({request:data});
});
api.post('/public/quotations/:token/payment-order',async(req,res)=>{if(!env.RAZORPAY_KEY_ID||!env.RAZORPAY_KEY_SECRET){res.status(503).json({error:'Online payments are not configured yet.'});return;}const hash=createHash('sha256').update(req.params.token).digest('hex');const {data:q}=await admin.from('quotations').select('id,organization_id,project_id,total,status').eq('public_token_hash',hash).maybeSingle();if(!q||q.status!=='ACCEPTED'){res.status(409).json({error:'Accept the quotation before paying the advance.'});return;}const amount=Math.round(Number(q.total)*0.25);if(amount<=0){res.status(409).json({error:'The advance amount must be at least one rupee.'});return;}const razorpay=new Razorpay({key_id:env.RAZORPAY_KEY_ID,key_secret:env.RAZORPAY_KEY_SECRET});try{const order=await razorpay.orders.create({amount,currency:'INR',receipt:`adv-${q.id.slice(0,20)}`});const {error}=await admin.from('payments').insert({organization_id:q.organization_id,project_id:q.project_id,gateway:'RAZORPAY',gateway_order_id:order.id,amount,currency:'INR',status:'CREATED'});if(error)throw error;res.status(201).json({orderId:order.id,amount,currency:'INR',keyId:env.RAZORPAY_KEY_ID});}catch{res.status(502).json({error:'Could not start the payment. Please try again.'});}});
api.post('/webhooks/razorpay',async(req:RazorRequest,res)=>{
  if(!env.RAZORPAY_WEBHOOK_SECRET||!req.rawBody){res.status(503).json({error:'Payment webhook is not configured.'});return;}
  const signature=req.header('x-razorpay-signature')||'';
  const expected=createHmac('sha256',env.RAZORPAY_WEBHOOK_SECRET).update(req.rawBody).digest();
  let received:Buffer;
  try{received=Buffer.from(signature,'hex');}catch{res.status(400).json({error:'Invalid signature.'});return;}
  if(received.length!==expected.length||!timingSafeEqual(received,expected)){res.status(400).json({error:'Invalid signature.'});return;}
  const eventId=req.header('x-razorpay-event-id')||'';
  const event=(req.body as any)?.event;
  if(event==='payment.captured'||event==='order.paid'){
    const payment=(req.body as any)?.payload?.payment?.entity;
    const order=(req.body as any)?.payload?.order?.entity;
    const orderId=payment?.order_id||order?.id,paymentId=payment?.id;
    if(orderId&&paymentId){const {data,error}=await admin.rpc('apply_captured_payment',{p_order_id:orderId,p_payment_id:paymentId,p_event_id:eventId||`evt-${paymentId}`});if(error||!data){res.status(500).json({error:'Payment could not be recorded.'});return;}}
  }else if(event==='payment.failed'){
    const payment=(req.body as any)?.payload?.payment?.entity,orderId=payment?.order_id;
    if(orderId){const {error}=await admin.from('payments').update({status:'FAILED',gateway_payment_id:payment?.id||null,webhook_event_id:eventId||null}).eq('gateway_order_id',orderId).in('status',['CREATED','AUTHORIZED']);if(error){res.status(500).json({error:'Payment failure could not be recorded.'});return;}}
  }else if(event==='refund.processed'){
    const refund=(req.body as any)?.payload?.refund?.entity,payment=(req.body as any)?.payload?.payment?.entity;
    const refundId=refund?.id,paymentId=refund?.payment_id||payment?.id,amount=Number(refund?.amount);
    if(refundId&&paymentId&&Number.isSafeInteger(amount)&&amount>0){const {data,error}=await admin.rpc('apply_processed_refund',{p_refund_id:refundId,p_payment_id:paymentId,p_amount:amount,p_event_id:eventId||`refund-${refundId}`});if(error||!data){res.status(500).json({error:'Refund could not be reconciled.'});return;}}
  }
  res.json({received:true});
});api.post('/quotations',authenticate,async(req:RequestWithAuth,res)=>{if(!allowRoles(req,res,['OWNER','ADMIN','PHOTOGRAPHER']))return;if(!await ensureActiveStudio(req.orgId,res))return;const p=z.object({projectId:z.string().uuid(),lineItems:z.array(z.object({description:z.string().min(1).max(200),quantity:z.number().positive(),unitAmount:z.number().int().nonnegative()})).min(1).max(100),discount:z.number().int().nonnegative().default(0),tax:z.number().int().nonnegative().default(0),terms:z.string().max(3000).optional(),expiresAt:z.string().datetime().optional()}).safeParse(req.body);if(!p.success){res.status(400).json({error:'Add at least one quotation item.'});return;}const {data:project}=await admin.from('projects').select('id').eq('id',p.data.projectId).eq('organization_id',req.orgId).maybeSingle();if(!project){res.status(404).json({error:'Project not found.'});return;}const subtotal=p.data.lineItems.reduce((sum,item)=>sum+Math.round(item.quantity*item.unitAmount),0);const total=Math.max(0,subtotal-p.data.discount+p.data.tax);const number=`Q-${new Date().getFullYear()}-${randomUUID().slice(0,8).toUpperCase()}`;const token=randomBytes(32).toString('base64url');const {data,error}=await admin.from('quotations').insert({organization_id:req.orgId,project_id:p.data.projectId,number,line_items:p.data.lineItems,subtotal,discount:p.data.discount,tax:p.data.tax,total,terms:p.data.terms||'',expires_at:p.data.expiresAt||null,public_token_hash:createHash('sha256').update(token).digest('hex'),status:'SENT'}).select('id,number,total,status').single();if(error){res.status(500).json({error:'Could not create the quotation.'});return;}await admin.from('projects').update({status:'QUOTATION_SENT',total_amount:total}).eq('id',p.data.projectId);res.status(201).json({quotation:data,customerLink:`/quote/${token}`});});
