api.get('/public/invoices/:token',async(req,res)=>{const hash=createHash('sha256').update(req.params.token).digest('hex');const {data,error}=await admin.from('invoices').select('id,number,kind,line_items,subtotal,discount,tax,total,amount_paid,currency,due_date,status,created_at,projects(name,organizations(name))').eq('public_token_hash',hash).maybeSingle();if(error||!data){res.status(404).json({error:'Invoice link is invalid.'});return;}res.json({invoice:data,balance:Math.max(0,Number(data.total)-Number(data.amount_paid))});});
api.post('/public/invoices/:token/payment-order',async(req,res)=>{if(!env.RAZORPAY_KEY_ID||!env.RAZORPAY_KEY_SECRET){res.status(503).json({error:'Online payments are not configured yet.'});return;}const hash=createHash('sha256').update(req.params.token).digest('hex');const {data:inv}=await admin.from('invoices').select('id,organization_id,project_id,total,amount_paid,currency,status').eq('public_token_hash',hash).maybeSingle();if(!inv){res.status(404).json({error:'Invoice link is invalid.'});return;}const amount=Number(inv.total)-Number(inv.amount_paid);if(amount<=0){res.status(409).json({error:'This invoice has no balance due.'});return;}const razorpay=new Razorpay({key_id:env.RAZORPAY_KEY_ID,key_secret:env.RAZORPAY_KEY_SECRET});try{const order=await razorpay.orders.create({amount,currency:inv.currency,receipt:`inv-${inv.id.slice(0,20)}`});const {error}=await admin.from('payments').insert({organization_id:inv.organization_id,project_id:inv.project_id,invoice_id:inv.id,gateway:'RAZORPAY',gateway_order_id:order.id,amount,currency:inv.currency,status:'CREATED'});if(error)throw error;res.status(201).json({orderId:order.id,amount,currency:inv.currency,keyId:env.RAZORPAY_KEY_ID});}catch{res.status(502).json({error:'Could not start the invoice payment.'});}});api.get('/public/quotations/:token',async(req,res)=>{const hash=createHash('sha256').update(req.params.token).digest('hex');const {data,error}=await admin.from('quotations').select('id,number,line_items,subtotal,discount,tax,total,terms,status,expires_at,projects(name,total_amount,amount_paid,organizations(name))').eq('public_token_hash',hash).maybeSingle();if(error||!data){res.status(404).json({error:'Quotation link is invalid or expired.'});return;}if(data.expires_at&&new Date(data.expires_at)<new Date()){res.status(410).json({error:'This quotation has expired.'});return;}res.json({quotation:data});});
api.post('/public/quotations/:token/accept',async(req,res)=>{const hash=createHash('sha256').update(req.params.token).digest('hex');const {data,error}=await admin.from('quotations').update({status:'ACCEPTED',accepted_at:new Date().toISOString(),updated_at:new Date().toISOString()}).eq('public_token_hash',hash).in('status',['SENT','VIEWED']).or('expires_at.is.null,expires_at.gt.'+new Date().toISOString()).select('id,organization_id,project_id,total').maybeSingle();if(error||!data){res.status(404).json({error:'Quotation cannot be accepted.'});return;}await admin.from('projects').update({status:'BOOKED',total_amount:data.total}).eq('id',data.project_id);res.json({accepted:true});});api.get('/media/:id/status',authenticate,async(req:RequestWithAuth,res)=>{const {data:media}=await admin.from('media').select('id,provider,stream_video_id,status').eq('id',req.params.id).eq('organization_id',req.orgId).maybeSingle();if(!media){res.status(404).json({error:'Media not found in this studio.'});return;}if(media.provider!=='STREAM'||!media.stream_video_id){res.json({status:media.status});return;}if(!env.CLOUDFLARE_ACCOUNT_ID||!env.CLOUDFLARE_STREAM_API_TOKEN){res.status(503).json({error:'Video processing status is unavailable.'});return;}try{const response=await fetch(`https://api.cloudflare.com/client/v4/accounts/${env.CLOUDFLARE_ACCOUNT_ID}/stream/${media.stream_video_id}`,{headers:{Authorization:`Bearer ${env.CLOUDFLARE_STREAM_API_TOKEN}`}});const payload=await response.json() as {success?:boolean;result?:{status?:{state?:string;errorReasonCode?:string;errorReasonText?:string};duration?:number;input?:{width?:number;height?:number}}};if(!response.ok||!payload.success||!payload.result){res.status(502).json({error:'Could not check video processing status.'});return;}const state=payload.result.status?.state||'processing';if(state==='ready'){await admin.from('media').update({status:'READY',duration_seconds:payload.result.duration??null,width:payload.result.input?.width??null,height:payload.result.input?.height??null,updated_at:new Date().toISOString()}).eq('id',media.id).eq('organization_id',req.orgId);res.json({status:'READY'});return;}if(state==='error'){await admin.from('media').update({status:'FAILED',updated_at:new Date().toISOString()}).eq('id',media.id).eq('organization_id',req.orgId);res.json({status:'FAILED',error:payload.result.status?.errorReasonText||'Video processing failed.'});return;}res.json({status:'PROCESSING',providerStatus:state});}catch{res.status(502).json({error:'Could not check video processing status.'});}});api.get('/gallery-assets/:projectId',authenticate,async(req:RequestWithAuth,res)=>{const {data:project}=await admin.from('projects').select('id').eq('id',req.params.projectId).eq('organization_id',req.orgId).maybeSingle();if(!project){res.status(404).json({error:'Project not found.'});return;}const {data,error}=await admin.from('media').select('id,filename,mime_type,file_size_bytes,status').eq('organization_id',req.orgId).eq('project_id',project.id).is('gallery_id',null).eq('status','READY').order('created_at',{ascending:false});if(error){res.status(500).json({error:'Could not load project media.'});return;}res.json({media:data||[]});});
api.post('/galleries/:id/attach',authenticate,async(req:RequestWithAuth,res)=>{if(!allowRoles(req,res,['OWNER','ADMIN','PHOTOGRAPHER','EDITOR']))return;const p=z.object({mediaIds:z.array(z.string().uuid()).min(1).max(500)}).safeParse(req.body);if(!p.success){res.status(400).json({error:'Select at least one media item.'});return;}const {data:g}=await admin.from('galleries').select('id,project_id').eq('id',req.params.id).eq('organization_id',req.orgId).maybeSingle();if(!g){res.status(404).json({error:'Gallery not found.'});return;}const {data:media}=await admin.from('media').select('id').in('id',p.data.mediaIds).eq('organization_id',req.orgId).eq('project_id',g.project_id).is('gallery_id',null);if(!media||media.length!==p.data.mediaIds.length){res.status(400).json({error:'Some selected media does not belong to this project.'});return;}const {data:portfolioItems}=await admin.from('studio_portfolio_items').select('media_id').eq('organization_id',req.orgId).in('media_id',p.data.mediaIds);if((portfolioItems||[]).length){res.status(409).json({error:'Remove public portfolio images from the directory before adding them to a private client gallery.'});return;}const {error}=await admin.from('media').update({gallery_id:g.id,updated_at:new Date().toISOString()}).in('id',p.data.mediaIds);if(error){res.status(500).json({error:'Could not add media to the gallery.'});return;}res.json({attached:media.length});});api.post('/galleries',authenticate,async(req:RequestWithAuth,res)=>{if(!allowRoles(req,res,['OWNER','ADMIN','PHOTOGRAPHER','EDITOR']))return;if(!await ensureActiveStudio(req.orgId,res))return;const p=z.object({projectId:z.string().uuid(),title:z.string().trim().min(2).max(120),description:z.string().max(1000).optional(),expiresAt:z.string().datetime().optional()}).safeParse(req.body);if(!p.success){res.status(400).json({error:'Enter a gallery title and project.'});return;}const {data:project}=await admin.from('projects').select('id').eq('id',p.data.projectId).eq('organization_id',req.orgId).maybeSingle();if(!project){res.status(404).json({error:'Project not found.'});return;}const token=randomBytes(32).toString('base64url');const {data:g,error}=await admin.from('galleries').insert({organization_id:req.orgId,project_id:p.data.projectId,title:p.data.title,description:p.data.description||'',access_token_hash:createHash('sha256').update(token).digest('hex'),expires_at:p.data.expiresAt||null,enabled:true,downloads_require_payment:true,allow_streaming:true}).select('id,title').single();if(error){res.status(500).json({error:'Could not create the gallery.'});return;}res.status(201).json({gallery:g,customerLink:`/gallery/${token}`});});
api.post('/projects/:id/customer-invitation',authenticate,async(req:RequestWithAuth,res)=>{if(!allowRoles(req,res,['OWNER','ADMIN','PHOTOGRAPHER']))return;if(!await ensureActiveStudio(req.orgId,res))return;const p=z.object({galleryId:z.string().uuid(),galleryToken:z.string().min(32).max(200)}).safeParse(req.body);if(!p.success){res.status(400).json({error:'Choose a valid project gallery.'});return;}const tokenHash=createHash('sha256').update(p.data.galleryToken).digest('hex');const [{data:project},{data:gallery}]=await Promise.all([admin.from('projects').select('id,clients(name,email)').eq('id',req.params.id).eq('organization_id',req.orgId).maybeSingle(),admin.from('galleries').select('id').eq('id',p.data.galleryId).eq('project_id',req.params.id).eq('organization_id',req.orgId).eq('access_token_hash',tokenHash).maybeSingle()]);if(!project||!gallery){res.status(404).json({error:'Project or gallery not found.'});return;}const client=project.clients as any;const email=String(client?.email||'').trim();if(!email){res.status(400).json({error:'Add an email address to this project client before sending an invitation.'});return;}const {data,error}=await admin.auth.admin.inviteUserByEmail(email,{redirectTo:`${env.WEB_ORIGIN}/gallery/${encodeURIComponent(p.data.galleryToken)}`,data:{customer_name:client.name||''}});if(error){const already=/already|registered|exists/i.test(error.message);res.status(already?409:502).json({error:already?'This email already has an account. Share the private gallery link so the customer can sign in and continue.':'Could not send the customer invitation. Check Supabase Auth email settings.'});return;}if(!data.user){res.status(502).json({error:'The invitation email could not be confirmed.'});return;}await admin.from('audit_logs').insert({organization_id:req.orgId,actor_user_id:req.userId,action:'CUSTOMER_GALLERY_INVITED',target_type:'gallery',target_id:gallery.id,details:{project_id:req.params.id}});res.status(201).json({invited:true,email});});api.get('/public/galleries/:token',async(req,res)=>{const hash=createHash('sha256').update(req.params.token).digest('hex');const {data:g}=await admin.from('galleries').select('id,title,description,organization_id,project_id,expires_at,enabled,downloads_require_payment,allow_streaming,projects(id,name,total_amount,amount_paid,organizations(name))').eq('access_token_hash',hash).maybeSingle();if(!g||!g.enabled){res.status(404).json({error:'This gallery is unavailable.'});return;}if(g.expires_at&&new Date(g.expires_at)<new Date()){res.status(410).json({error:'This gallery link has expired.'});return;}const {data:media,error}=await admin.from('media').select('id,filename,mime_type,file_size_bytes,provider,status,width,height,duration_seconds').eq('gallery_id',g.id).eq('status','READY').order('created_at');if(error){res.status(500).json({error:'Could not load this gallery.'});return;}const project=g.projects as any;const paid=Number(project.amount_paid)>=Number(project.total_amount);await admin.from('audit_logs').insert({organization_id:g.organization_id,action:'GALLERY_VIEW',target_type:'gallery',target_id:g.id,details:{project_id:g.project_id}});res.json({gallery:{id:g.id,title:g.title,description:g.description,studio:project.organizations?.name,project:project.name,paid,downloadsUnlocked:!g.downloads_require_payment||paid,totalAmount:Number(project.total_amount),amountPaid:Number(project.amount_paid)},media:media||[]});});
api.get('/public/galleries/:token/invoices',async(req,res)=>{const hash=createHash('sha256').update(req.params.token).digest('hex');const {data:g}=await admin.from('galleries').select('id,project_id,enabled,expires_at').eq('access_token_hash',hash).maybeSingle();if(!g||!g.enabled||g.expires_at&&new Date(g.expires_at)<new Date()){res.status(404).json({error:'Gallery is unavailable.'});return;}const {data,error}=await admin.from('invoices').select('id,number,kind,line_items,subtotal,discount,tax,total,amount_paid,currency,due_date,status,created_at').eq('project_id',g.project_id).order('created_at',{ascending:false});if(error){res.status(500).json({error:'Could not load project invoices.'});return;}res.json({invoices:data||[]});});
api.get('/public/galleries/:token/media/:mediaId/access',async(req,res)=>{const hash=createHash('sha256').update(req.params.token).digest('hex');const {data:g}=await admin.from('galleries').select('id,enabled,expires_at,downloads_require_payment,allow_streaming,projects(total_amount,amount_paid)').eq('access_token_hash',hash).maybeSingle();if(!g||!g.enabled||g.expires_at&&new Date(g.expires_at)<new Date()){res.status(404).json({error:'Gallery is unavailable.'});return;}const {data:m}=await admin.from('media').select('*').eq('id',req.params.mediaId).eq('gallery_id',g.id).eq('status','READY').maybeSingle();if(!m){res.status(404).json({error:'Media item not found.'});return;}const project=g.projects as any;const paid=Number(project.amount_paid)>=Number(project.total_amount);if(m.provider==='STREAM'){if(!g.allow_streaming||!env.CLOUDFLARE_ACCOUNT_ID||!env.CLOUDFLARE_STREAM_API_TOKEN||!env.CLOUDFLARE_STREAM_CUSTOMER_CODE){res.status(403).json({error:'Video playback is unavailable.'});return;}const video=await fetch(`https://api.cloudflare.com/client/v4/accounts/${env.CLOUDFLARE_ACCOUNT_ID}/stream/${m.stream_video_id}/token`,{method:'POST',headers:{Authorization:`Bearer ${env.CLOUDFLARE_STREAM_API_TOKEN}`,'Content-Type':'application/json'},body:JSON.stringify({downloadable:!g.downloads_require_payment||paid,exp:Math.floor(Date.now()/1000)+3600})});const payload=await video.json() as {success?:boolean;result?:{token?:string}};if(!video.ok||!payload.success||!payload.result?.token){res.status(502).json({error:'Could not prepare secure video playback.'});return;}res.json({type:'video',playbackUrl:`https://iframe.videodelivery.net/${payload.result.token}`,downloadUnlocked:!g.downloads_require_payment||paid});return;}const key=(!g.downloads_require_payment||paid)?m.original_object_key:m.preview_object_key;if(!key){res.status(403).json({error:paid?'This image is not available yet.':'A preview for this photo is not ready yet.'});return;}try{const url=await getSignedUrl(objectStore,new GetObjectCommand({Bucket:env.R2_BUCKET,Key:key}),{expiresIn:600});res.json({type:'image',url,downloadUnlocked:!g.downloads_require_payment||paid});}catch{res.status(502).json({error:'Could not prepare this photo.'});}});
api.get('/public/galleries/:token/media/:mediaId/download',async(req,res)=>{const hash=createHash('sha256').update(req.params.token).digest('hex');const {data:g}=await admin.from('galleries').select('id,enabled,expires_at,downloads_require_payment,projects(total_amount,amount_paid)').eq('access_token_hash',hash).maybeSingle();if(!g||!g.enabled||g.expires_at&&new Date(g.expires_at)<new Date()){res.status(404).json({error:'Gallery is unavailable.'});return;}const project=g.projects as any;const paid=Number(project.amount_paid)>=Number(project.total_amount);if(g.downloads_require_payment&&!paid){res.status(402).json({error:'Complete the project payment to unlock downloads.'});return;}const {data:m}=await admin.from('media').select('provider,original_object_key,filename,stream_video_id').eq('id',req.params.mediaId).eq('gallery_id',g.id).eq('status','READY').maybeSingle();if(!m){res.status(404).json({error:'Media item not found.'});return;}if(m.provider==='STREAM'){if(!env.CLOUDFLARE_ACCOUNT_ID||!env.CLOUDFLARE_STREAM_API_TOKEN||!env.CLOUDFLARE_STREAM_CUSTOMER_CODE){res.status(503).json({error:'Video download is not configured.'});return;}const statusResponse=await fetch(`https://api.cloudflare.com/client/v4/accounts/${env.CLOUDFLARE_ACCOUNT_ID}/stream/${m.stream_video_id}/downloads`,{headers:{Authorization:`Bearer ${env.CLOUDFLARE_STREAM_API_TOKEN}`}});const statusData=await statusResponse.json() as {result?:{default?:{status?:string}}};if(!statusResponse.ok||statusData.result?.default?.status!=='ready'){res.status(409).json({error:'The video download is still being prepared. Try again later.'});return;}const tokenResponse=await fetch(`https://api.cloudflare.com/client/v4/accounts/${env.CLOUDFLARE_ACCOUNT_ID}/stream/${m.stream_video_id}/token`,{method:'POST',headers:{Authorization:`Bearer ${env.CLOUDFLARE_STREAM_API_TOKEN}`,'Content-Type':'application/json'},body:JSON.stringify({downloadable:true,exp:Math.floor(Date.now()/1000)+300})});const tokenData=await tokenResponse.json() as {success?:boolean;result?:{token?:string}};if(!tokenResponse.ok||!tokenData.success||!tokenData.result?.token){res.status(502).json({error:'Could not prepare the video download.'});return;}res.json({url:`https://customer-${env.CLOUDFLARE_STREAM_CUSTOMER_CODE}.cloudflarestream.com/${tokenData.result.token}/downloads/default.mp4`,expiresIn:300});return;}try{const url=await getSignedUrl(objectStore,new GetObjectCommand({Bucket:env.R2_BUCKET,Key:m.original_object_key,ResponseContentDisposition:`attachment; filename="${safeFilename(m.filename)}"`}),{expiresIn:300});res.json({url,expiresIn:300});}catch{res.status(502).json({error:'Could not prepare this download.'});}});
api.post('/public/galleries/:token/payment-order',async(req,res)=>{if(!env.RAZORPAY_KEY_ID||!env.RAZORPAY_KEY_SECRET){res.status(503).json({error:'Online payments are not configured yet.'});return;}const hash=createHash('sha256').update(req.params.token).digest('hex');const {data:g}=await admin.from('galleries').select('id,project_id,organization_id,projects(id,total_amount,amount_paid)').eq('access_token_hash',hash).eq('enabled',true).maybeSingle();if(!g){res.status(404).json({error:'Gallery is unavailable.'});return;}const project=g.projects as any;const amount=Number(project.total_amount)-Number(project.amount_paid);if(amount<=0){res.status(409).json({error:'There is no remaining balance.'});return;}let invoiceId:string;const {data:pending}=await admin.from('invoices').select('id').eq('project_id',g.project_id).eq('organization_id',g.organization_id).eq('kind','FINAL').in('status',['DRAFT','SENT','PARTIALLY_PAID']).order('created_at',{ascending:false}).limit(1).maybeSingle();if(pending){invoiceId=pending.id;}else{const number=`FIN-${new Date().getFullYear()}-${randomUUID().slice(0,8).toUpperCase()}`;const {data:invoice,error}=await admin.from('invoices').insert({organization_id:g.organization_id,project_id:g.project_id,number,kind:'FINAL',line_items:[{description:'Final project balance',quantity:1,unitAmount:amount}],subtotal:amount,total:amount,currency:'INR',status:'SENT'}).select('id').single();if(error||!invoice){res.status(500).json({error:'Could not create the final invoice.'});return;}invoiceId=invoice.id;}const razorpay=new Razorpay({key_id:env.RAZORPAY_KEY_ID,key_secret:env.RAZORPAY_KEY_SECRET});try{const order=await razorpay.orders.create({amount,currency:'INR',receipt:`bal-${project.id.slice(0,20)}`});const {error}=await admin.from('payments').insert({organization_id:g.organization_id,project_id:g.project_id,invoice_id:invoiceId,gateway:'RAZORPAY',gateway_order_id:order.id,amount,currency:'INR',status:'CREATED'});if(error)throw error;res.status(201).json({orderId:order.id,amount,currency:'INR',keyId:env.RAZORPAY_KEY_ID});}catch{res.status(502).json({error:'Could not start the balance payment.'});}});app.use('/api',api);app.use((err:unknown,_req:express.Request,res:express.Response,_next:express.NextFunction)=>{console.error(err);res.status(500).json({error:'Something went wrong. Please try again.'});});app.listen(env.PORT,()=>console.log(`Photo Gallery API listening on ${env.PORT}`));














































